import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.C3fpVp7C.js";const b=JSON.parse('{"title":"4. Bun executables and tag-driven releases","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0004-bun-executables-and-tag-releases.md","filePath":"adr/0004-bun-executables-and-tag-releases.md","lastUpdated":1792160181000}'),o={name:"adr/0004-bun-executables-and-tag-releases.md"};function r(l,e,d,i,c,u){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="_4-bun-executables-and-tag-driven-releases" tabindex="-1">4. Bun executables and tag-driven releases <a class="header-anchor" href="#_4-bun-executables-and-tag-driven-releases" aria-label="Permalink to &quot;4. Bun executables and tag-driven releases&quot;">​</a></h1><p>Status: accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Users who only want the CLI or the server should not need a Node.js install. The Node.js build uses <code>better-sqlite3</code>, a native addon that a single-file executable cannot load. The project first used release-please, which cut releases from merged pull requests, while the artifacts needed a build on a tag.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Standalone executables are compiled with <code>bun build --compile</code> for Linux x64 and arm64, macOS x64 and arm64, and Windows x64. On Bun, <code>openDatabase()</code> uses the built-in <code>bun:sqlite</code> driver, whose API covers every call the package makes. A pushed <code>v*</code> tag runs one workflow that builds the executables, the multi-arch image and the npm tarball, smoke-tests each on its platform, attaches them to the GitHub Release with <code>SHA256SUMS</code>, an SPDX SBOM and provenance attestations, signs the image with cosign and publishes the npm package. release-please was removed so that there is one release path.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>One download runs the CLI and the server on each supported platform.</li><li>Two SQLite drivers must stay compatible. The smoke test runs every executable against a real grant, check, revoke and audit sequence.</li><li>Releases need a manual version bump and CHANGELOG entry before the tag.</li></ul>',8)])])}const p=a(o,[["render",r]]);export{b as __pageData,p as default};
